export const complianceIndex = {"docTitle":"Employment compliance by country | Taito.ai","eyebrow":"Compliance","title":"Employment compliance, country by country","description":"Practical up-to-date guides to annual leave, sick pay, working time and statutory deadlines, ready-made for each country you employ in. Get familiar with the employer requirements and learn how to avoid common pitfalls, whether you're employing at home or abroad.","markets":{"eyebrow":"Markets","title":"Which country do you employ in?","items":[{"name":"Finland","description":"Generally binding collective agreements, the annual leave accrual year, working time accounts and the ten-weekday sick pay window.","href":"/compliance/finland","flag":"/assets/pages/compliance-legal/flag-fi.svg"},{"name":"Sweden","description":"Collective agreements, annual leave and holiday pay under the Annual Leave Act, and where employer-paid sick pay hands over to the social insurance agency.","href":"/compliance/sweden","flag":"/assets/pages/compliance-legal/flag-se.svg"},{"name":"Norway","description":"Holiday pay, the employer-paid sick pay period, working time and collective agreements under Norwegian law.","href":"/compliance/norway","flag":"/assets/pages/compliance-legal/flag-no.svg"},{"name":"Estonia","description":"Annual leave counted in calendar days, the sick pay window you carry from day four to day eight, attendance limits and the flexible working time agreement introduced in 2026.","href":"/compliance/estonia","flag":"/assets/pages/compliance-legal/flag-ee.svg"},{"name":"United Kingdom","description":"Statutory sick pay after the April 2026 reform, holiday pay for irregular-hours workers, the 48-hour week and the day-one written statement.","href":"/compliance/uk","flag":"/assets/pages/compliance-legal/flag-gb.svg"},{"name":"Netherlands","description":"The chain rule that turns a fixed-term contract permanent, two years of continued pay during sick leave, holiday pay at eight percent, and the closed list of nine grounds for dismissal.","href":"/compliance/netherlands","flag":"/assets/pages/compliance-legal/flag-nl.svg"}]},"guidelines":{"eyebrow":"Common guidelines for employers","title":"Three checks before your first hire in a new country","items":[{"title":"Check for a collective agreement first","body":"In some countries one covers you even if you never signed it, and it sets higher minimum pay than the law does. Find out before you offer a salary, because it changes every number after that."},{"title":"Put the contract in writing on time","body":"Every country makes you give new employees written terms, usually by their first day. It is quick to do, and it is the first document anyone asks for when there is a disagreement."},{"title":"Check the holiday and sick pay dates","body":"Holiday is earned over a set period that rarely matches your financial year, and you pay sick leave for a fixed number of days before the state takes over. Both differ by country, so do not copy them from home."}]}};

